{
  "name": "tldr",
  "version": "0.2.7",
  "private": true,
  "type": "module",
  "description": "TLDR — community tl;dr notes for any web page. Monorepo root: canonical shared code + repo-level checks.",
  "license": "MIT",
  "scripts": {
    "build": "npm --prefix extension run build",
    "sync-shared": "node dev/build/tools/sync-shared.mjs",
    "test": "node --test \"shared/test/**/*.test.mjs\" \"dev/build/tools/test/**/*.test.mjs\"",
    "test:all": "npm test && npm --prefix server ci && npm --prefix server test && npm --prefix extension test && npm --prefix dev ci && npm --prefix dev test"
  }
}
---
import commentClassMenu from './comment-class-menu.mjs';

// TLDR's own pack — the repo-level lessons that aren't a canon rule and have no
// home in the mounted canon. Most are prose because their deterministic half is
// already guarded elsewhere (a canon check, a workflow gate), so what's left to
// carry is the judgment — which file is authoritative, which direction a fix
// goes, and which "obvious" guard would break the release pipeline. A lesson
// that CAN be made deterministic becomes a rule in this pack instead, not a
// paragraph in RULES.md.
//
// Longer-form, activity-scoped project guidance stays where this repo already
// keeps it (dev/procedures/, routed from its CLAUDE.md); this pack is for the
// short, always-on rules the engine injects into every session.
export default {
  id: 'tldr',
  ruleRoutingGuidance: {
    belongs: "TLDR's repo-level lessons — which file is authoritative, which direction a fix goes, release-pipeline gotchas",
    excludes: 'general software-engineering practice and portable procedure — those live in the vendored Claudinite canon',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [],
  workRules: [commentClassMenu],
};

// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
// task that opened a PR — or an `open-pr` task that merged one — fails the run
// and converges to needs-human. "No change" is always legal.
//
// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
// what the task did to PULL REQUESTS.

import { OUTCOMES } from './task-contract.mjs';

// Verify what a task actually did against its declared ceiling.
//   outcome    — the task's declared ceiling ('none' | 'open-pr' | 'merged-pr')
//   openedPr   — did the run open a pull request?
//   mergedPr   — did the run merge (or arm auto-merge on) a pull request?
// Returns { ok, violation } — violation is null when within the ceiling.
export function verifyOutcome({ outcome, openedPr = false, mergedPr = false }) {
  if (!OUTCOMES.includes(outcome)) {
    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
  }
  // Merging implies a PR exists; treat a merge as also having opened one so a
  // caller that only reports mergedPr is still judged correctly.
  const opened = openedPr || mergedPr;

  if (outcome === 'none' && opened) {
    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
  }
  if (outcome === 'open-pr' && mergedPr) {
    return { ok: false, violation: 'an "open-pr" task must not merge a pull request' };
  }
  return { ok: true, violation: null };
}

